import * as api from './api.js';
import {esc,brl,dt,shortDt,initials,icon,pill,empty,formField,selectField,statusMap,statusPill,dateInput} from './ui.js';
import {campaignMutationFromForm,createNotificationController,createSegmentListController,filterTasks,isTaskOverdue} from './p1-ui.js';
import {createAutomationEditor,type AutomationGateway} from './automation-ui.js';
import {IMPORT_API_MAX_ROWS,parseCsvPreview,validateImportJobPayload,pollJob} from './import-report-ui.js';

type Row=api.Row;
type Page='dashboard'|'contacts'|'pipeline'|'tasks'|'calendar'|'campaigns'|'segments'|'automations'|'reports'|'integrations'|'team'|'settings';
const root=document.getElementById('root')!;
const pages:{id:Page;name:string;symbol:string;group:string}[]=[
 {id:'dashboard',name:'Visão geral',symbol:'grid',group:'PRINCIPAL'},
 {id:'contacts',name:'Leads & contatos',symbol:'users',group:'PRINCIPAL'},
 {id:'pipeline',name:'Pipeline comercial',symbol:'columns',group:'PRINCIPAL'},
 {id:'tasks',name:'Tarefas',symbol:'checksquare',group:'OPERAÇÃO'},
 {id:'calendar',name:'Calendário',symbol:'calendar',group:'OPERAÇÃO'},
 {id:'campaigns',name:'Campanhas',symbol:'megaphone',group:'OPERAÇÃO'},
 {id:'segments',name:'Listas de segmentos',symbol:'users',group:'INTELIGÊNCIA'},
 {id:'automations',name:'Automações',symbol:'bolt',group:'INTELIGÊNCIA'},
 {id:'reports',name:'Relatórios',symbol:'chart',group:'INTELIGÊNCIA'},
 {id:'integrations',name:'Leads Hub & API',symbol:'link',group:'SISTEMA'},
 {id:'team',name:'Equipe',symbol:'user',group:'SISTEMA'},
 {id:'settings',name:'Configurações',symbol:'settings',group:'SISTEMA'}
];
const s:{user:Row|null;members:Row[];workspaces:Row[];workspace:string;role:string;page:Page;data:Record<string,Row[]>;summary:Row;query:string;status:string;month:Date;busy:boolean;drawer:string;menu:boolean;isSuperAdmin:boolean;platformWorkspaces:Row[];showCompleted:boolean;overdueOnly:boolean}={
 user:null,members:[],workspaces:[],workspace:'',role:'viewer',page:'dashboard',data:{},summary:{},query:'',status:'',month:new Date(),busy:false,drawer:'',menu:false,isSuperAdmin:false,platformWorkspaces:[],showCompleted:false,overdueOnly:false
};
const now=()=>new Date();
const roleLabel:Record<string,string>={owner:'Proprietário',admin:'Administrador',marketing_manager:'Gerente de Marketing',sdr:'SDR',closer:'Closer',viewer:'Leitura'};
const canContactWrite=()=>['owner','admin','marketing_manager','sdr','closer'].includes(s.role);
const canTaskWrite=()=>['owner','admin','sdr','closer'].includes(s.role);
const canDealCreate=()=>['owner','admin','closer','sdr'].includes(s.role);
const canDealEdit=()=>['owner','admin','closer'].includes(s.role);
const canMarketingWrite=()=>['owner','admin','marketing_manager'].includes(s.role);
const canAdmin=()=>['owner','admin'].includes(s.role);
const canDelete=()=>['owner','admin'].includes(s.role);
const canAutomationsRead=()=>['owner','admin','marketing_manager','viewer'].includes(s.role);
const canAutomationsWrite=()=>['owner','admin','marketing_manager'].includes(s.role);
const canAutomationKillSwitch=()=>['owner','admin'].includes(s.role);
const canReportsRead=()=>['owner','admin','marketing_manager','sdr','closer','viewer'].includes(s.role);
const canSegmentsRead=()=>canReportsRead();
const canSegmentsWrite=()=>['owner','admin','marketing_manager'].includes(s.role);
const canManageSegmentMembership=()=>['owner','admin','marketing_manager'].includes(s.role);
const canMarkNotificationsRead=()=>!!s.user&&!!s.workspace;
const canImportContacts=()=>canContactWrite();
let automationEditor:ReturnType<typeof createAutomationEditor>|null=null;
const items=(key:string)=>s.data[key]||[];
const activeWorkspace=()=>s.workspaces.find(w=>w.id===s.workspace);
const toSlug=(v:string)=>v.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,35);
const dateOnly=(d:Date)=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const email=()=>s.user?.email||'Usuário';
const displayName=()=>email().split('@')[0].replace(/[._-]/g,' ').replace(/\b\w/g,(m:string)=>m.toUpperCase());
function toast(message:string,type=''){document.querySelector('.notice')?.remove();const el=document.createElement('div');el.className='notice '+type;el.setAttribute('role','status');el.textContent=message;document.body.appendChild(el);setTimeout(()=>el.remove(),4800)}
function errorText(e:unknown){return e instanceof Error?e.message:String(e)}
function fail(e:unknown){console.error(e);toast(errorText(e),'error')}
function el(id:string){return document.getElementById(id)}
function closeOverlay(){document.getElementById('overlay')?.remove();document.getElementById('drawer-overlay')?.remove()}

function actionButton(text:string,action:string,kind='primary',symbol='plus'){return `<button class="btn ${kind}" data-action="${action}">${icon(symbol,15)}${esc(text)}</button>`}
function header(title:string,desc:string,actions=''){return `<div class="page-intro"><div><div class="eyebrow">CENTRAL DE OPERAÇÃO</div><h1>${esc(title)}</h1><p class="subtitle">${esc(desc)}</p></div><div class="header-actions">${actions}</div></div>`}
function sidebar(){
 const workspace=activeWorkspace();
 const identity=workspace?.logo_path?`<img class="ws-logo" src="${esc(api.companyLogoUrl(workspace.logo_path))}" alt="Logo ${esc(workspace.name)}">`:`<div class="ws-initial">${esc(initials(workspace?.name||'MC'))}</div>`;
 let prev='';const nav=pages.map(p=>{const label=p.group!==prev?`<div class="sidebar-title">${p.group}</div>`:'';prev=p.group;return `${label}<button class="nav-item ${s.page===p.id?'active':''}" data-nav="${p.id}" aria-current="${s.page===p.id?'page':'false'}">${icon(p.symbol,18)}<span>${p.name}</span></button>`}).join('');
 return `<div class="scrim ${s.menu?'open':''}" data-action="close-menu"></div><aside class="sidebar ${s.menu?'open':''}"><div class="brand"><img src="./assets/core-mark.svg" alt=""><div><b>marketing core</b><small>CRM / SYSTEM</small></div></div><div class="workspace-identity">${identity}<span class="name"><strong>${esc(workspace?.name||'Workspace')}</strong><small>${esc(roleLabel[s.role]||s.role)}</small></span></div><nav class="nav-list" aria-label="Navegação principal">${nav}</nav><div class="sidebar-bottom"><button class="sidebar-mini" data-action="logout">${icon('logout',17)}Sair da conta</button><div class="sidebar-mini" style="font-size:10px;color:#6687A4"><span class="online-dot"></span> Supabase · v2.4</div></div></aside>`
}
function shell(content:string){const pg=pages.find(x=>x.id===s.page)!;const unread=items('core_notifications').filter(n=>!n.read_at).length;return `<div class="app-shell">${sidebar()}<main class="main-area"><header class="topbar"><div class="crumb"><button class="top-icon sidebar-toggle" data-action="toggle-menu" aria-label="Abrir menu">${icon('menu',20)}</button><span class="padded-crumb">Marketing Core</span>${icon('right',13)}<strong>${esc(pg.name)}</strong></div><div class="topbar-end"><label class="top-search">${icon('search',16)}<input type="search" id="top-search" placeholder="Buscar contatos..." aria-label="Buscar contatos"></label><button class="top-icon" data-action="show-notifications" title="Notificações" aria-label="Notificações${unread?` (${unread} não lidas)`:''}">${icon('activity',19)}${unread?`<span class="notification-badge">${unread}</span>`:''}</button><button class="top-icon" data-nav="tasks" title="Minhas tarefas">${icon('checksquare',19)}</button><div class="userbox"><div class="avatar">${esc(initials(displayName()))}</div><div class="usertext"><strong>${esc(displayName())}</strong><small>${esc(roleLabel[s.role]||s.role)}</small></div></div></div></header><div class="main-content" id="page-content">${content}</div></main></div>`}
function infoMsg(txt:string){return `<div class="banner">${icon('info',17)}<div>${txt}</div></div>`}
function leadRequestScreen(message=''){
 const submissionId=crypto.randomUUID();
 root.innerHTML=`<div class="login-shell"><section class="login-visual"><div class="login-brand"><img src="./assets/core-mark.svg" alt="Marketing Core"><div>marketing core<small>CRM / SYSTEM</small></div></div><div class="login-copy"><span class="nudge">SOLICITE UMA APRESENTAÇÃO</span><h1>Conheça o CRM.<br><span>Depois decida com clareza.</span></h1><p>Conte sobre sua operação. A Marketing Core entrará em contato antes da criação de qualquer acesso.</p></div><div class="login-footer">Marketing começa no Core. © ${new Date().getFullYear()}</div></section><section class="login-right"><div class="login-card"><span class="small-tag">MARKETING CORE CRM</span><h2>Solicitar acesso</h2><p class="hint">Preencha seus dados para conversar com nosso time.</p>${message?infoMsg(esc(message)):''}<form data-form="lead-request"><input type="hidden" name="submission_id" value="${submissionId}"><div class="form-grid"><label class="field"><span>NOME *</span><input name="name" autocomplete="name" required></label><label class="field"><span>WHATSAPP *</span><input name="phone" type="tel" placeholder="(31) 99999-9999" autocomplete="tel" required></label><label class="field"><span>E-MAIL *</span><input name="email" type="email" autocomplete="email" required></label><label class="field"><span>EMPRESA *</span><input name="company" autocomplete="organization" required></label><label class="field"><span>TAMANHO DA EQUIPE</span><input name="team_size" type="number" min="1" max="999" placeholder="Ex.: 5"></label><label class="field"><span>PRINCIPAL NECESSIDADE *</span><input name="challenge" placeholder="Leads, vendas, atendimento..." required></label></div><label class="checkrow"><input name="consent" type="checkbox" required> Autorizo a Marketing Core a entrar em contato sobre esta solicitação.</label><button class="btn primary" type="submit">Enviar solicitação${icon('right',16)}</button></form><div class="footline"><button data-auth="login">Já tenho acesso</button></div><div class="secure-line">${icon('shield',14)} O envio não cria usuário nem libera acesso automaticamente</div></div></section></div>`
}
function normalizeLeadPhone(value:string){const digits=value.replace(/\D/g,'');const national=digits.startsWith('55')?digits.slice(2):digits;if(national.length!==11||national[2]!=='9')throw Error('Informe um celular brasileiro válido com DDD.');return '+55'+national}
function authScreen(view='login',message=''){
 if(view==='signup'){leadRequestScreen(message);return}
 const labels:{[k:string]:string}={login:'Acesse sua operação',signup:'Crie sua conta',recover:'Recuperar acesso',password:'Definir nova senha'};
 root.innerHTML=`<div class="login-shell"><section class="login-visual"><div class="login-brand"><img src="./assets/core-mark.svg" alt="Marketing Core"><div>marketing core<small>CRM / SYSTEM</small></div></div><div class="login-copy"><span class="nudge">SISTEMA COMERCIAL</span><h1>Clareza para decidir.<br><span>Controle para crescer.</span></h1><p>Do primeiro lead ao fechamento. Um núcleo de dados, pessoas e oportunidades para acelerar sua operação.</p><div class="login-lines"><i></i><i></i><i></i></div></div><div class="login-footer">Marketing começa no Core. © ${new Date().getFullYear()}</div></section><section class="login-right"><div class="login-card"><span class="small-tag">MARKETING CORE CRM</span><h2>${labels[view]||labels.login}</h2><p class="hint">${view==='signup'?'Um ambiente seguro para sua equipe.':view==='recover'?'Enviaremos um link para seu e-mail.':view==='password'?'Escolha uma senha forte para concluir a recuperação.':'Entre com seu e-mail corporativo para continuar.'}</p>${!api.configured()?`<div class="banner warning">${icon('alert')}<div>Instalação pendente: configure a URL e a chave pública do Supabase em <strong>crm/config.js</strong>, após aplicar a migration.</div></div>`:''}${message?infoMsg(esc(message)):''}<form data-form="auth-${view}">${view!=='password'?`<label class="field"><span>E-MAIL</span><input name="email" type="email" placeholder="voce@suaempresa.com.br" autocomplete="username" required></label>`:''}${['login','signup','password'].includes(view)?`<label class="field"><span>SENHA</span><input name="password" type="password" minlength="8" required autocomplete="${view==='login'?'current-password':'new-password'}" placeholder="Mínimo 8 caracteres"></label>`:''}<button class="btn primary" type="submit" ${!api.configured()?'disabled':''}>${view==='login'?'Entrar no CRM':view==='signup'?'Criar conta':view==='password'?'Atualizar senha':'Enviar link'}${icon('right',16)}</button></form><div class="footline">${view==='login'?`<button class="plain-link" data-action="auth-recover">Esqueci minha senha</button><button class="plain-link" data-action="auth-signup">Criar conta</button>`: `<button class="plain-link" data-action="auth-login">Voltar para login</button>`}</div><div class="login-trust">${icon('shield',16)} Autenticação Supabase · acessos por empresa e função</div></div></section></div>`;
}
async function boot(){
 if(!api.configured()){authScreen();return}
 try{if(await api.exchangeRecoveryHash()){authScreen('password');return}}catch(e){fail(e)}
 if(!api.loadSession()){authScreen();return}
 try{s.user=await api.getUser();await hydrateWorkspace();}catch(e){api.clearSession();authScreen('login','Sua sessão expirou. Entre novamente.');}
}
async function hydrateWorkspace(){
 if(!s.user)return;
 // Invitation accepted only by the verified Auth email, never by user-supplied user_id.
 const invite=new URLSearchParams(location.search).get('invite');
 if(invite&&/^[a-f\d-]{36}$/i.test(invite)){
  try{await api.rpc('core_accept_invitation',{p_invitation:invite});history.replaceState(null,'',location.pathname);toast('Convite aceito. Bem-vindo à equipe.');}
  catch(e){toast('Convite pendente: '+errorText(e),'error')}
 }
 try{
  const accepted=await api.rpc('core_accept_my_pending_invitations',{});
  if(Array.isArray(accepted)&&accepted.length)toast('Convite aceito. Bem-vindo à equipe.');
 }catch(e){console.warn('Não foi possível verificar convites pendentes',e)}
 s.isSuperAdmin=await api.rpc('core_is_super_admin',{});
 const memberships=await api.select('core_memberships',{user_id:`eq.${s.user.id}`,active:'eq.true'},{order:'joined_at.asc'});
 s.members=memberships;
 const all=await api.select('core_workspaces',{}, {order:'created_at.asc'});
 s.platformWorkspaces=s.isSuperAdmin?all:[];
 s.workspaces=all.filter((w:Row)=>w.state==='active'&&memberships.some((m:Row)=>m.workspace_id===w.id));
 const stored=sessionStorage.getItem('marketing_core_workspace');
 s.workspace=s.workspaces.some(w=>w.id===stored)?stored||'':s.workspaces[0]?.id||'';
 s.role=memberships.find((m:Row)=>m.workspace_id===s.workspace)?.role||'viewer';
 if(!s.workspace){if(s.isSuperAdmin)renderPlatform();else renderOnboarding();return}
 await navigate(s.page);
}
function renderOnboarding(){root.innerHTML=`<div class="onboard"><div class="onboard-card"><img src="./assets/core-mark.svg" alt="Marketing Core" width="56"><h1>Acesso aguardando convite</h1><p>Sua identidade já está autenticada. Um administrador deve convidar seu e-mail verificado para uma empresa. Se recebeu o link de convite, abra-o neste navegador.</p><button class="plain-link" data-action="logout">Sair da conta</button></div></div>`}
function renderPlatform(){
 const rows=s.platformWorkspaces.map(w=>`<tr><td><strong>${esc(w.name)}</strong><br><small>${esc(w.slug)}</small></td><td>${pill(w.state==='active'?'Ativa':'Suspensa',w.state==='active'?'green':'red')}</td><td>${esc(w.max_members)}</td><td><button class="btn small" data-action="platform-invite" data-id="${w.id}">Convidar owner</button> <button class="btn small" data-action="platform-resend-owner" data-id="${w.id}">Reenviar acesso</button> <button class="btn small" data-action="platform-state" data-id="${w.id}" data-state="${w.state}">${w.state==='active'?'Suspender':'Reativar'}</button></td></tr>`).join('');
 root.innerHTML=`<div class="onboard" style="align-items:flex-start;padding:7vh 4%"><section class="surface" style="width:min(1080px,100%);margin:auto"><div class="eyebrow">GOVERNANÇA DA PLATAFORMA</div><h1>Marketing Core · Administração</h1><p class="section-note">Visão de empresas e estados. Dados operacionais não são abertos pelo papel global.</p><div class="header-actions" style="justify-content:flex-start;margin:18px 0"><button class="btn primary" data-action="platform-new">${icon('plus')} Nova empresa</button>${s.workspaces.length?`<button class="btn" data-action="back-crm">Voltar ao CRM</button>`:''}<button class="btn" data-action="logout">Sair</button></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Empresa</th><th>Estado</th><th>Vagas máximas</th><th>Controle</th></tr></thead><tbody>${rows||'<tr><td colspan="4">Nenhuma conta empresarial criada.</td></tr>'}</tbody></table></div></section></div>`;
}
let navigationVersion=0;
async function navigate(page:Page){if(!s.workspace)return; const version=++navigationVersion;s.page=page;s.query='';s.status='';s.menu=false;const p=pages.find(x=>x.id===page)!;root.innerHTML=shell(`<div class="preload" style="min-height:55vh">${icon(p.symbol,31)}<p>Sincronizando ${esc(p.name.toLowerCase())}...</p></div>`);try{await loadPage(page);if(version===navigationVersion)renderPage();}catch(e){if(version!==navigationVersion)return;console.error(e);const area=el('page-content');if(area)area.innerHTML=header('Não foi possível carregar','Os dados operacionais não são substituídos por dados fictícios.')+`<div class="surface">${empty('Falha ao carregar',errorText(e),'alert')}<div style="text-align:center"><button class="btn primary" data-action="reload-page">Tentar novamente</button></div></div>`;}}
async function loadPage(page:Page){
 const tables:Record<Page,string[]>={dashboard:['core_contacts','core_tasks'],contacts:['core_contacts','core_tags','core_contact_tags'],pipeline:['core_pipelines','core_stages','core_deals','core_contacts'],tasks:['core_tasks','core_contacts'],calendar:['core_tasks'],campaigns:['core_campaigns'],segments:['core_segment_lists','core_segment_list_members','core_contacts'],automations:['core_automation_settings'],reports:['core_contacts','core_deals','core_campaigns','core_report_jobs'],integrations:['core_ingestion_events','core_forms'],team:['core_memberships','core_invitations'],settings:['core_tags']};
 const query=[...new Set(tables[page])];
 const tableOrder:Record<string,string>={core_stages:'position.asc',core_memberships:'joined_at.asc',core_tags:'name.asc',core_contact_tags:'tag_id.asc',core_ingestion_events:'received_at.desc',core_automation_settings:'updated_at.desc',core_segment_list_members:'added_at.desc'};
 await Promise.all([api.list('core_notifications',s.workspace,{order:'created_at.desc'},100).then(rows=>s.data.core_notifications=rows),...query.map(async t=>{s.data[t]=await api.list(t,s.workspace,{order:tableOrder[t]||'created_at.desc'},500)})]);
 if(page==='team'){
  const directory=await api.rpc('core_member_display_names',{w:s.workspace}) as Row[];
  const names=new Map(directory.map(x=>[x.user_id,x.full_name]));
  items('core_memberships').forEach(m=>m.display_name=names.get(m.user_id)||'Membro');
  s.members=[...s.members.filter(m=>m.workspace_id!==s.workspace),...items('core_memberships')];
 }
 if(['dashboard','reports'].includes(page))s.summary=await api.rpc('core_dashboard_summary',{p_workspace:s.workspace});
}
function renderPage(){automationEditor?.destroy();automationEditor=null;const content:Record<Page,()=>string>={dashboard:dashboard,contacts:contacts,pipeline:pipeline,tasks:tasks,calendar:calendar,campaigns:campaigns,segments:segments,automations:automations,reports:reports,integrations:integrations,team:team,settings:settings};const area=el('page-content');if(area){area.innerHTML=content[s.page]();if(s.page==='automations')void mountAutomationEditor();}}
function memberName(id:string){if(!id)return'Não atribuído';return s.members.find(m=>m.workspace_id===s.workspace&&m.user_id===id)?.display_name||'Membro'}
function metric(name:string,number:string,foot:string,symbol:string,tint=''){return `<div class="metric"><div class="metric-top"><span>${esc(name)}</span><div class="metric-icon ${tint}">${icon(symbol,17)}</div></div><strong>${esc(number)}</strong><div class="metric-foot">${esc(foot)}</div></div>`}
function dashboard(){
 const d=s.summary;const count=Number(d.contacts||0);const daily=(d.daily||[]) as Row[];
 const dayData=Array.from({length:14},(_,i)=>{const date=new Date();date.setDate(date.getDate()-13+i);const value=daily.find(x=>x.day===dateOnly(date));return {day:date.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'}),value:Number(value?.count||0)}});
 const max=Math.max(1,...dayData.map(x=>x.value));const counts=d.funnel||{};
 const bars=dayData.map(x=>`<div class="barcol" title="${esc(x.day)}: ${x.value} leads"><div class="bar" style="height:${Math.max(2,x.value/max*100)}%"></div><label>${x.day.slice(0,2)}</label></div>`).join('');
 const funnel=[['new','Novo lead'],['contacted','Contactado'],['qualified','Qualificado'],['customer','Cliente']].map(([k,label])=>`<div class="funnel-line"><span class="funnel-name">${label}</span><div class="funnel-track"><div class="funnel-fill" style="width:${count?Number(counts[k]||0)/count*100:0}%"></div></div><span class="funnel-count">${Number(counts[k]||0)}</span></div>`).join('');
 const recent=items('core_contacts').slice(0,6).map(c=>`<div class="mini-row"><div class="mini-avatar">${esc(initials(c.name))}</div><div class="mini-main"><button class="text-button" data-action="open-contact" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.source||c.company||'Origem não informada')}</small></div>${statusPill(c.status)}</div>`).join('')||empty('Ainda sem leads','Crie seu primeiro contato ou conecte um formulário.');
 const due=items('core_tasks').filter(t=>t.status==='todo').sort((a,b)=>(a.due_at||'9').localeCompare(b.due_at||'9')).slice(0,6).map(t=>`<div class="mini-row"><div class="mini-avatar" style="background:#FFF4E9;color:#B7862F">${icon('clock',16)}</div><div class="mini-main"><strong>${esc(t.title)}</strong><small>${t.due_at?dt(t.due_at):'Sem prazo definido'}</small></div><button class="icon-btn" data-action="complete-task" data-id="${t.id}" title="Concluir tarefa">${icon('check',17)}</button></div>`).join('')||empty('Tudo em dia','Nenhuma tarefa pendente.','checksquare');
 return header('Sua operação em um só lugar','Indicadores reais para priorizar o que importa.',actionButton('Novo lead','new-contact')+actionButton('Novo negócio','new-deal','soft','plus'))+
 `<div class="layout-grid">${metric('Total de contatos',String(count),'Base consolidada','users','teal')}${metric('Leads nos últimos 30 dias',String(d.new_30d||0),'Captados no período','activity')}${metric('Valor em negociação',brl(d.pipeline_value),'${Number(d.open_deals||0)} negócios abertos','chart','green')}${metric('Tarefas próximas',String(d.tasks_due||0),'Pendentes até amanhã','clock','gold')}</div>
 <div class="two-col"><section class="panel"><div class="panel-header"><div><h2>Entradas de leads</h2><p>Volume diário · últimos 14 dias</p></div>${pill('Dados reais','cyan')}</div><div class="panel-body"><div class="bars">${bars}</div><div class="legend">Leads recebidos</div></div></section><section class="panel"><div class="panel-header"><div><h2>Etapas de relacionamento</h2><p>Distribuição atual por status</p></div></div><div class="panel-body">${funnel}<div class="block-divider"></div><div class="section-note">${count} contatos em todos os estágios.</div></div></section></div>
 <div class="two-col"><section class="panel"><div class="panel-header"><div><h2>Contatos recentes</h2><p>Últimas oportunidades registradas</p></div><button class="panel-link" data-nav="contacts">Ver todos ${icon('right',13)}</button></div><div class="panel-body">${recent}</div></section><section class="panel"><div class="panel-header"><div><h2>Próximas atividades</h2><p>Acompanhe entregas e compromissos</p></div><button class="panel-link" data-nav="tasks">Todas ${icon('right',13)}</button></div><div class="panel-body">${due}</div></section></div>`;
}
function contactRows(){const all=items('core_contacts');const q=s.query.toLowerCase().trim();const results=all.filter(c=>(!q||[c.name,c.email,c.phone,c.company,c.source].some(v=>String(v||'').toLowerCase().includes(q)))&&(!s.status||c.status===s.status));return results;}
function contactTable(rows:Row[]){return rows.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Contato</th><th>Empresa / telefone</th><th>Origem</th><th>Status</th><th>Responsável</th><th>Entrada</th><th></th></tr></thead><tbody>${rows.map(c=>`<tr><td><div class="contact-name"><div class="mini-avatar">${esc(initials(c.name))}</div><div><button class="text-button" data-action="open-contact" data-id="${c.id}">${esc(c.name)}</button><small>${esc(c.email||'E-mail não cadastrado')}</small></div></div></td><td>${esc(c.company||'—')}<br><small>${esc(c.phone||'')}</small></td><td>${esc(c.source||'—')}</td><td>${statusPill(c.status)}</td><td>${esc(memberName(c.owner_id))}</td><td>${dt(c.created_at)}</td><td><button class="icon-btn" data-action="open-contact" data-id="${c.id}" title="Ver contato">${icon('right',16)}</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum contato encontrado','Experimente outro filtro ou registre um novo contato.','users')}
function contacts(){return header('Leads & contatos','Seu relacionamento com cada oportunidade, do primeiro sinal ao fechamento.',canContactWrite()?actionButton('Novo contato','new-contact')+(canImportContacts()?actionButton('Importar CSV','import-csv','soft','download'):''):'' )+
 `<section class="panel"><div class="table-toolbar"><div class="table-search">${icon('search',16)}<input aria-label="Pesquisar contatos" id="contacts-search" type="search" value="${esc(s.query)}" placeholder="Buscar nome, e-mail, empresa..."></div><div class="filters"><select id="contacts-status" aria-label="Filtrar status"><option value="">Todos os status</option>${Object.entries(statusMap).filter(([k])=>['new','contacted','qualified','customer','lost'].includes(k)).map(([k,v])=>`<option value="${k}" ${s.status===k?'selected':''}>${v}</option>`).join('')}</select><button class="btn small" data-action="export-contacts">${icon('download',14)} Exportar CSV</button></div></div><div id="contacts-table">${contactTable(contactRows())}</div><div class="table-toolbar" style="border-top:1px solid var(--line)"><span class="section-note" id="contacts-count">${contactRows().length} contato(s) exibido(s)</span><span class="section-note">Cada alteração é persistida no Supabase</span></div></section>`}
function dealCard(d:Row){const c=items('core_contacts').find(c=>c.id===d.contact_id);const editable=canDealEdit()||(s.role==='sdr'&&d.owner_id===s.user?.id);return `<article class="deal-card" draggable="${editable}" data-deal="${d.id}" data-action="edit-deal" data-id="${d.id}" tabindex="0"><b>${esc(d.name)}</b><p>${esc(c?.name||'Contato não localizado')}</p><strong>${brl(d.value)}</strong><div class="deal-bottom"><small>${esc(memberName(d.owner_id))}</small>${statusPill(d.status)}</div></article>`}
function pipeline(){const stages=items('core_stages');const deals=items('core_deals');const pipes=items('core_pipelines');let pipe=pipes.find(p=>p.is_default)||pipes[0];const pipeStages=stages.filter(x=>x.pipeline_id===pipe?.id).sort((a,b)=>a.position-b.position);const board=pipeStages.map(st=>{const cards=deals.filter(d=>d.stage_id===st.id);return `<div class="board-column" data-stage="${st.id}"><div class="board-head"><span class="dot" style="background:${st.outcome==='won'?'#2AAF82':st.outcome==='lost'?'#DE6A77':'#7174F1'}"></span>${esc(st.name)}<span class="count">${cards.length}</span></div><div class="board-value">${brl(cards.reduce((a,d)=>a+Number(d.value),0))}</div>${cards.map(dealCard).join('')}${canDealCreate()?`<button class="deal-add" data-action="new-deal" data-stage="${st.id}">+ Novo negócio</button>`:''}</div>`}).join('');return header('Pipeline comercial','Acompanhe negociações em cada etapa e movimente as oportunidades.',canDealCreate()?actionButton('Novo negócio','new-deal'):'')+`<div class="banner">${icon('info')}<div>Arraste cartões entre as etapas para registrar a movimentação. A mudança é gravada no banco, incluindo o status de ganho ou perda.</div></div><div class="board" aria-label="Quadro de negócios">${board||empty('Crie seu pipeline','Abra um workspace para começar.')}</div>`}
function taskList(rows:Row[]){return rows.length?rows.map(t=>`<div class="task-row ${t.status==='done'?'is-done':''} ${isTaskOverdue(t as any)?'is-overdue':''}"><input type="checkbox" aria-label="Concluir ${esc(t.title)}" data-task-check="${t.id}" ${t.status==='done'?'checked':''} ${!canTaskWrite()?'disabled':''}><div class="task-content"><strong>${esc(t.title)}</strong><small>${t.description?esc(t.description).slice(0,120)+' · ':''}${t.due_at?dt(t.due_at):'Sem prazo'} · ${esc(memberName(t.assigned_to))}</small></div>${isTaskOverdue(t as any)?pill('Atrasada','red'):t.priority==='high'?pill('Alta prioridade','red'):''}<button class="icon-btn" title="Editar tarefa" data-action="edit-task" data-id="${t.id}" ${!canTaskWrite()?'disabled':''}>${icon('edit',15)}</button></div>`).join(''):empty('Nenhuma tarefa por aqui','Crie uma tarefa para manter o relacionamento no ritmo certo.','checksquare')}
function tasks(){const list=filterTasks(items('core_tasks') as any[],{showCompleted:s.showCompleted,overdueOnly:s.overdueOnly}).sort((a,b)=>(a.due_at||'9').localeCompare(b.due_at||'9'));return header('Tarefas & prioridades','O próximo passo de cada negociação, com donos e prazos claros.',canTaskWrite()?actionButton('Nova tarefa','new-task'):'')+`<section class="panel"><div class="table-toolbar"><div><h2 style="margin:0">Sua lista de atividades</h2><p class="section-note" style="margin:6px 0 0">${list.length} tarefas no filtro atual</p></div><div class="filters"><label class="checkrow"><input id="tasks-overdue" type="checkbox" ${s.overdueOnly?'checked':''}> Somente atrasadas</label><label class="checkrow"><input id="tasks-completed" type="checkbox" ${s.showCompleted?'checked':''}> Mostrar concluídas</label></div></div><div id="tasks-list">${taskList(list)}</div></section>`}
function calendar(){const yr=s.month.getFullYear(),mo=s.month.getMonth();const first=new Date(yr,mo,1),start=first.getDay(),max=new Date(yr,mo+1,0).getDate();const cells:Array<{day:number;other:boolean;date:string}>=[];for(let i=0;i<42;i++){const day=i-start+1;const date=new Date(yr,mo,day);cells.push({day:date.getDate(),other:day<1||day>max,date:dateOnly(date)})}const events=items('core_tasks');const markup=cells.map(c=>{const tasks=events.filter(t=>t.due_at&&String(t.due_at).slice(0,10)===c.date);return `<div class="calendar-day ${c.other?'other':''} ${c.date===dateOnly(now())?'today':''}"><span class="number">${c.day}</span>${tasks.slice(0,3).map(t=>`<div class="calendar-item" title="${esc(t.title)}" data-action="edit-task" data-id="${t.id}">${esc(t.title)}</div>`).join('')}${tasks.length>3?`<div class="calendar-item">+${tasks.length-3} itens</div>`:''}</div>`}).join('');return header('Calendário de atividades','Visualize prazos da equipe e antecipe possíveis gargalos.',(canTaskWrite()?actionButton('Agendar tarefa','new-task'):'')+(['owner','admin','sdr','closer'].includes(s.role)?actionButton('Minha conta Google','google-status','soft','calendar'):'') )+`<section class="panel"><div class="panel-header"><div><h2>${s.month.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</h2><p>Tarefas com data definida</p></div><div class="header-actions"><button class="btn small" data-action="month-prev">${icon('left',15)}</button><button class="btn small" data-action="month-now">Hoje</button><button class="btn small" data-action="month-next">${icon('right',15)}</button></div></div><div class="calendar">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>`<div class="day-head">${d}</div>`).join('')}${markup}</div></section>`}
function campaigns(){const cards=items('core_campaigns').map(c=>`<div class="entity-card"><div class="entity-meta"><span>${esc(c.channel||'Campanha')}</span>${statusPill(c.status)}</div><h3>${esc(c.name)}</h3><p>${c.start_date?dt(c.start_date):'Sem data inicial'}${c.end_date?' — '+dt(c.end_date):''}</p><div class="entity-meta"><div><small>Orçamento</small><div class="entity-value">${c.budget==null?'Não informado':brl(c.budget)}</div></div><div><small>Investido</small><div class="entity-value">${c.spent==null?'Não informado':brl(c.spent)}</div></div></div><div class="progressbar"><span style="width:${Math.min(100,Number(c.budget)>0?Number(c.spent||0)/Number(c.budget)*100:0)}%"></span></div><div class="entity-foot"><small>Controle de orçamento</small>${canMarketingWrite()?`<button class="btn small" data-action="edit-campaign" data-id="${c.id}">${icon('edit',14)} Editar</button>`:''}</div></div>`).join('');return header('Campanhas','Planejamento e execução sem perder controle de investimentos.',canMarketingWrite()?actionButton('Nova campanha','new-campaign'):'')+`<div class="card-grid">${cards||empty('Nenhuma campanha','Registre suas campanhas e acompanhe orçamento e gastos.','megaphone')}</div>`}
function segments(){if(!canSegmentsRead())return header('Listas de segmentos','Organize públicos por objetivo.')+empty('Acesso negado','Sua função não possui a capacidade reports.read.','alert');const lists=items('core_segment_lists');const members=items('core_segment_list_members');const cards=lists.map(x=>`<article class="entity-card"><div class="entity-meta">${pill(x.category||'CUSTOM','slate')}<strong>${members.filter(m=>m.list_id===x.id).length} membro(s)</strong></div><h3>${esc(x.name)}</h3><p>${esc(x.description||'Sem descrição')}</p><div class="entity-foot"><button class="btn small" data-action="segment-members" data-id="${x.id}">Membros</button>${canSegmentsWrite()?`<button class="btn small" data-action="edit-segment" data-id="${x.id}">Editar</button><button class="btn small danger" data-action="delete-segment" data-id="${x.id}">Excluir</button>`:''}</div></article>`).join('');return header('Listas de segmentos','CRUD e associação de contatos com escopo do workspace.',canSegmentsWrite()?actionButton('Nova lista','new-segment'):'')+`<div class="card-grid">${cards||empty('Nenhuma lista','Crie uma lista para organizar contatos.','users')}</div>`}
function automations(){if(!canAutomationsRead())return header('Automações','Fluxos publicados e executados com segurança.')+empty('Acesso negado','Sua função não possui automations.read.','alert');const enabled=items('core_automation_settings')[0]?.automation_enabled===true;return header('Automações','Publique revisões validadas e controle sua execução.',canAutomationKillSwitch()?`<button class="btn ${enabled?'danger':'soft'}" data-action="automation-kill">${enabled?'Pausar todas':'Reativar execução'}</button>`:'')+(!canAutomationsWrite()?infoMsg('Modo leitura: sua função não possui automations.write.'):'')+`<div id="automation-editor-root" class="surface"></div>`}
async function mountAutomationEditor(){const host=el('automation-editor-root');if(!host||!canAutomationsRead())return;const gateway:AutomationGateway={
 list:async workspaceId=>api.rpc('core_automation_list',{p_workspace:workspaceId}),
 read:async(workspaceId,ruleId)=>api.rpc('core_automation_read',{p_workspace:workspaceId,p_rule_id:ruleId}),
 publish:async input=>{if(!canAutomationsWrite())throw Error('Sem a capacidade automations.write.');return api.rpc('core_automation_publish',{p_workspace:input.workspaceId,p_rule_id:input.ruleId,p_name:input.name,p_graph:input.graph,p_expected_hash:null})},
 activate:async(workspaceId,ruleId,revisionId)=>{if(!canAutomationsWrite())throw Error('Sem a capacidade automations.write.');await api.rpc('core_automation_activate',{p_workspace:workspaceId,p_rule_id:ruleId,p_revision_id:revisionId})},
 pause:async(workspaceId,ruleId)=>{if(!canAutomationsWrite())throw Error('Sem a capacidade automations.write.');await api.rpc('core_automation_pause',{p_workspace:workspaceId,p_rule_id:ruleId})},
};automationEditor=createAutomationEditor({root:host,workspaceId:s.workspace,gateway,onError:fail});await automationEditor.mount();if(!canAutomationsWrite())host.querySelectorAll<HTMLButtonElement>('button').forEach(b=>{if(b.dataset.action!=='open')b.disabled=true});}
function reports(){if(!canReportsRead())return header('Relatórios executivos','Exportações duráveis e autorizadas.')+empty('Acesso negado','Sua função não possui reports.read.','alert');const jobs=items('core_report_jobs');const rows=jobs.map(j=>`<div class="mini-row"><div class="mini-main"><strong>${esc(j.report_kind||j.kind)} · ${esc(j.status)}</strong><small>${Number(j.emitted_row_count||0)}/${Number(j.expected_row_count||0)} linhas${j.error_code?' · '+esc(j.error_code):''}</small></div>${j.status==='COMPLETED'?`<button class="btn small" data-action="download-report" data-id="${j.id}">Baixar</button>`:''}</div>`).join('');return header('Relatórios executivos','Jobs completos por snapshot, sem limite silencioso.',actionButton('Gerar relatório','new-report','soft','download'))+`<section class="panel"><div class="panel-header"><div><h2>Exportações</h2><p>O download usa artefato assinado e autorizado.</p></div></div><div class="panel-body" id="report-jobs">${rows||empty('Nenhum relatório','Gere um CSV de contatos, negócios ou tarefas.','chart')}</div></section>`}
async function showIntegrationKeys(){
 if(!canAdmin())throw Error('Sem permissão');
 const k=await api.fn('core-integration-keys',{workspace_id:s.workspace,action:'list'});
 const google=await api.rpc('core_google_status',{w:s.workspace});
 const rows=(k.keys||[]).map((x:Row)=>`<div class="mini-row"><strong>${esc(x.label)}</strong><span style="flex:1"></span>${pill(x.enabled?'Ativa':'Revogada',x.enabled?'green':'red')}${x.enabled?`<button class="btn small" data-action="integration-revoke" data-id="${x.id}">Revogar</button>`:''}</div>`).join('');
 closeOverlay();const node=document.createElement('div');node.id='overlay';node.className='overlay';node.innerHTML=`<div class="modal wide" role="dialog" aria-modal="true" aria-label="Integrações"><div class="modal-header"><h2>Integrações da empresa</h2><button class="icon-btn" data-action="close-overlay">${icon('close')}</button></div><div class="modal-body"><h3>Webhooks e chaves de API</h3>${rows||'<p>Nenhuma credencial criada.</p>'}<div class="header-actions"><button class="btn primary" data-action="integration-create-webhook">Novo webhook</button><button class="btn" data-action="integration-create-api">Nova chave de API</button></div><p class="section-note">Cada nova credencial é gravada imediatamente no Supabase. Revogue a antiga somente depois de atualizar o sistema emissor.</p><hr><h3>Google Calendar</h3><p>${google.connected?'Conectado: '+esc(google.email||'conta Google'):'Não conectado'}</p><button class="btn" data-action="${google.connected?'google-disconnect':'google-connect'}">${google.connected?'Desconectar':'Conectar Google'}</button><p class="section-note">OAuth só funciona após configurar credenciais e URLs do Google.</p></div></div>`;node.addEventListener('click',ev=>{if(ev.target===node)closeOverlay()});document.body.appendChild(node);
}
function integrations(){const events=items('core_ingestion_events');const forms=items('core_forms');const eRows=events.slice(0,12).map(e=>`<tr><td>${dt(e.received_at)}</td><td>${esc(e.source||'Leads Hub')}</td><td>${esc(e.form_id||'—')}</td><td>${statusPill(e.status==='completed'?'done':e.status)}</td><td><code style="font-size:10px">${esc(String(e.idempotency_key).slice(0,22))}${String(e.idempotency_key).length>22?'…':''}</code></td></tr>`).join('');return header('Leads Hub & integrações','Visibilidade sobre entradas de leads e os conectores autorizados.',canAdmin()?actionButton('Gerenciar API e Google','integration-keys')+actionButton('Novo formulário','new-form'):'')+
 `<div class="banner warning">${icon('shield')}<div><strong>Integração server-to-server.</strong> Use a opção API Key/Bearer no Leads Hub. HMAC continua disponível para integrações avançadas. Nunca coloque a chave no site público.</div></div><div class="split-panels"><section class="surface"><div class="eyebrow">ENDPOINT ONLINE</div><h2>Recebimento de leads</h2><p class="section-note">POST /functions/v1/core-webhook-v2</p><div class="code">${esc(api.config().url)}/functions/v1/core-webhook-v2</div><div class="info-block"><span>Leads Hub</span><strong>Auth Bearer + chave de API gerada aqui</strong></div><div class="info-block"><span>Webhook avançado</span><strong>X-Core-Ingest-Key + Timestamp + Signature HMAC</strong></div><div class="info-block"><span>Workspace</span><strong>Determinado no servidor pela chave cadastrada</strong></div><p class="section-note">Consulte <strong>docs/INTEGRACAO_LEADS_HUB.md</strong> no pacote privado para instruções, geração de chave e teste cURL.</p></section><section class="surface"><div class="eyebrow">FORMULÁRIOS</div><h2>Fontes cadastradas</h2>${forms.length?forms.map(f=>`<div class="mini-row"><div class="mini-avatar">${icon('link',16)}</div><div class="mini-main"><strong>${esc(f.name)}</strong><small>${esc(f.slug)} · ${esc(f.source||'Não definida')}</small></div>${pill(f.enabled?'Ativo':'Pausado',f.enabled?'green':'amber')}</div>`).join(''):empty('Nenhum formulário','Cadastre os identificadores de seus formulários para organizar origens.','link')}</section></div><section class="panel"><div class="panel-header"><div><h2>Histórico de recebimentos</h2><p>Eventos registrados com chave idempotente</p></div>${pill(`${events.length} eventos`,'cyan')}</div>${events.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Recebido</th><th>Origem</th><th>Formulário</th><th>Status</th><th>Chave idempotente</th></tr></thead><tbody>${eRows}</tbody></table></div>`:empty('Aguardando a primeira integração','Assim que um webhook for aceito, seu evento aparecerá aqui.','inbox')}</section>`}
