async function showRolePermissions(role='sdr'){
 if(!canAdmin())throw Error('Sem permissão');
 const r=await api.select('core_role_permissions',{workspace_id:`eq.${s.workspace}`,role:`eq.${role}`});
 const granted=new Map<string,boolean>(r.map((x:Row)=>[x.permission,!!x.enabled]));
 closeOverlay();const node=document.createElement('div');node.id='overlay';node.className='overlay';node.innerHTML=`<div class="modal wide" role="dialog" aria-modal="true" aria-label="Permissões da equipe"><div class="modal-header"><div><h2>Permissões da função ${esc(role.toUpperCase())}</h2><p>É possível restringir direitos existentes; nunca ampliar além do teto seguro da função.</p></div><button class="icon-btn" data-action="close-overlay">${icon('close')}</button></div><div class="modal-body"><div class="header-actions">${['sdr','closer','viewer'].map(x=>`<button class="btn small" data-action="role-select" data-id="${x}">${x.toUpperCase()}</button>`).join('')}</div><div class="form-grid">${(roleCapabilities[role]||[]).map(permission=>`<label class="checkrow"><input type="checkbox" data-permission="${permission}" data-role="${role}" ${granted.get(permission)!==false?'checked':''}> ${esc(permission)}</label>`).join('')}</div></div></div>`;node.addEventListener('click',ev=>{if(ev.target===node)closeOverlay()});document.body.appendChild(node);
}
function team(){
 const members=items('core_memberships');
 const invitations=items('core_invitations').filter(i=>i.status==='pending');
 const rows=members.map(m=>`<tr><td><div class="contact-name"><div class="mini-avatar">${icon('user',15)}</div><div><strong>${m.user_id===s.user?.id?esc(email()):'Membro '+esc(m.user_id.slice(0,8))}</strong><small>${esc(m.user_id)}</small></div></div></td><td>${pill(roleLabel[m.role]||m.role,m.role==='owner'?'violet':'slate')}</td><td>${pill(m.active?'Ativo':'Inativo',m.active?'green':'red')}</td><td>${dt(m.joined_at)}</td><td>${canAdmin()&&m.role!=='owner'?`<button class="btn small" data-action="edit-member" data-id="${m.user_id}">Permissões</button>`:''}</td></tr>`).join('');
 const inviteRows=invitations.map(i=>`<tr><td><strong>${esc(i.email)}</strong></td><td>${pill(roleLabel[i.role]||i.role,'slate')}</td><td>${pill('Pendente','gold')}</td><td>${dt(i.expires_at)}</td><td>${canAdmin()?`<button class="btn small" data-action="resend-invite" data-id="${i.id}">Reenviar</button> <button class="btn small" data-action="revoke-invite" data-id="${i.id}">Revogar</button>`:''}</td></tr>`).join('');
 return header('Equipe & acessos','Papéis são validados no banco; equipes de empresas diferentes não compartilham registros.',canAdmin()?actionButton('Configurar permissões','role-permissions')+actionButton('Convidar membro','invite-member'):'')+infoMsg('Novos usuários entram por convite do Supabase. Convites pendentes podem ser reenviados sem criar registros duplicados.')+`<section class="panel"><div class="panel-header"><div><h2>Membros deste workspace</h2><p>${members.length} usuário(s) autorizado(s)</p></div>${pill('RLS habilitada','green')}</div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Usuário</th><th>Função</th><th>Situação</th><th>Desde</th><th>Gerenciar</th></tr></thead><tbody>${rows}</tbody></table></div></section>${canAdmin()?`<section class="panel"><div class="panel-header"><div><h2>Convites pendentes</h2><p>${invitations.length} convite(s) aguardando aceite</p></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>E-mail</th><th>Função</th><th>Situação</th><th>Expira em</th><th>Gerenciar</th></tr></thead><tbody>${inviteRows||'<tr><td colspan="5">Nenhum convite pendente.</td></tr>'}</tbody></table></div></section>`:''}`;
}
