 if(a==='download-report'){if(!canReportsRead())throw Error('Sem a capacidade reports.read.');const result=await api.fn('core-report-jobs',{action:'download',job_id:id});const parts=Array.isArray(result.parts)?result.parts.filter((part:Row)=>typeof part.url==='string'):[];if(!parts.length)throw Error('Artefato assinado indisponível.');for(let index=0;index<parts.length;index++){const link=document.createElement('a');link.href=String(parts[index].url);link.download=`relatorio-${id}-parte-${index+1}.csv`;link.rel='noopener';document.body.appendChild(link);link.click();link.remove();}toast(`${parts.length} parte(s) do relatório preparada(s) para download.`);return}
