function formData(form:HTMLFormElement){const fd=new FormData(form);return Object.fromEntries(fd.entries()) as Row}
const optional=(v:any)=>String(v||'').trim()||null;
const iso=(v:any)=>v?new Date(String(v)).toISOString():null;
async function submitForm(form:HTMLFormElement){
 const name=form.dataset.form||'';const d=formData(form);const btn=form.querySelector('button[type=submit]') as HTMLButtonElement|undefined;const originalButtonHtml=btn?.innerHTML||'';if(btn){btn.disabled=true;btn.textContent='Salvando...'}
 try{
  if(name==='auth-login'){await api.signIn(String(d.email),String(d.password));s.user=await api.getUser();await hydrateWorkspace();return}
  if(name==='lead-request'){
   const submission_id=String(d.submission_id);const fields={name:String(d.name).trim(),phone:normalizeLeadPhone(String(d.phone)),email:String(d.email).trim().toLowerCase(),company:String(d.company).trim(),team_size:String(d.team_size||''),challenge:String(d.challenge).trim(),interest:'Marketing Core CRM',consent:true,submission_id};
   const params=new URLSearchParams(location.search);const common={form_name:'marketing_core_crm_access_request',source:'crm_login',submission_id,fields,tracking:{utm_source:params.get('utm_source')||'',utm_medium:params.get('utm_medium')||'',utm_campaign:params.get('utm_campaign')||''},page_url:location.href,wrdab_website:''};
   await api.captureAccessLead({...common,stage:'phone_captured'});await api.captureAccessLead({...common,stage:'email_captured'});await api.captureAccessLead({...common,stage:'completed'});
   root.innerHTML=`<div class="onboard"><div class="onboard-card"><img src="./assets/core-mark.svg" alt="Marketing Core" width="56"><h1>Solicitação recebida</h1><p>Obrigado pelo interesse no Marketing Core CRM. Nossa equipe analisará seu cenário e entrará em contato.</p><button class="btn primary" data-action="auth-login">Voltar ao login</button></div></div>`;return
  }
  if(name==='auth-recover'){await api.recover(String(d.email));authScreen('login','Se o e-mail estiver cadastrado, um link de recuperação será enviado.');return}
  if(name==='auth-password'){await api.updatePassword(String(d.password));authScreen('login','Senha atualizada. Entre com sua nova senha.');return}
  if(name==='workspace-create'){if(!s.isSuperAdmin)throw Error('Somente o superadministrador cria empresas');const r=await api.rpc('core_platform_create_workspace',{p_name:String(d.name).trim(),p_slug:String(d.slug).trim(),p_owner_email:optional(d.owner_email)});closeOverlay();s.platformWorkspaces=await api.select('core_workspaces',{});renderPlatform();if(r.invitation_id)prompt('Copie e envie somente ao responsável pelo e-mail informado:',location.origin+location.pathname+'?invite='+r.invitation_id);else toast('Empresa criada. Convide o primeiro proprietário.');return}
  if(name==='platform-invite'){if(!s.isSuperAdmin)throw Error('Negado');const r=await api.fn('core-invite-member',{workspace_id:d.workspace_id,action:'invite',email:String(d.email).trim().toLowerCase(),role:'owner'});closeOverlay();prompt('Link de acesso para o e-mail confirmado:',r.accept_url);renderPlatform();return}
  if(name==='workspace-edit'){await api.request(`/rest/v1/core_workspaces?id=eq.${s.workspace}`,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({name:d.name})});closeOverlay();await hydrateWorkspace();toast('Empresa atualizada.');return}
  if(name==='integration-key'){const kind=String(d.kind||'API');const r=await api.fn('core-integration-keys',{action:'create',workspace_id:s.workspace,label:`${kind} — ${d.label}`});closeOverlay();modal('Credencial criada','Copie agora: a chave secreta será mostrada somente nesta tela.',`<div class="info-block"><span>Endpoint</span><input class="filter-input" readonly value="${esc(api.config().url)}/functions/v1/core-webhook-v2"></div><div class="info-block"><span>Chave secreta</span><input class="filter-input" readonly value="${esc(r.key)}"></div><div class="banner">${icon('info')}<div><strong>Para o Leads Hub:</strong> destino Webhook genérico, método POST, autenticação Bearer, cole esta chave no campo Auth token. O backend também aceita o header X-Core-API-Key.</div></div>`,'credential-created',true);return}
  if(name==='credential-created'){closeOverlay();await showIntegrationKeys();return}
  if(name==='company-profile'){
   if(!canAdmin())throw Error('Somente proprietários e administradores alteram o perfil da empresa.');
   const workspace=activeWorkspace();if(!workspace)throw Error('Empresa não localizada.');
   const file=new FormData(form).get('logo') as File;let logoPath=workspace.logo_path||null;
   if(file&&file.size)logoPath=await api.uploadCompanyLogo(s.workspace,file);
   await api.request(`/rest/v1/core_workspaces?id=eq.${s.workspace}`,{method:'PATCH',headers:{'content-type':'application/json','Prefer':'return=representation'},body:JSON.stringify({name:String(d.name).trim(),logo_path:logoPath,logo_updated_at:file&&file.size?new Date().toISOString():workspace.logo_updated_at})});
   if(file&&file.size&&workspace.logo_path&&workspace.logo_path!==logoPath)api.deleteCompanyLogo(workspace.logo_path).catch(e=>console.warn('Logo antiga não removida',e));
   closeOverlay();await hydrateWorkspace();toast('Perfil da empresa atualizado.');return
  }
 
  if(name==='contact'){
   if(!canContactWrite())throw Error('Sem permissão para alterar contatos.');
   const body={name:String(d.name).trim(),email:optional(d.email),phone:optional(d.phone),company:optional(d.company),source:optional(d.source),status:d.status,owner_id:optional(d.owner_id),campaign:optional(d.campaign),notes:String(d.notes||''),consent:form.querySelector<HTMLInputElement>('input[name=consent]')?.checked||false};
   if(!body.email&&!body.phone)throw Error('Informe pelo menos telefone ou e-mail.');
   if(d.id)await api.update('core_contacts',String(d.id),s.workspace,body);else await api.insert('core_contacts',{workspace_id:s.workspace,...body,consent_at:body.consent?new Date().toISOString():null});
   closeOverlay();toast('Contato salvo no Supabase.');await navigate('contacts');return
  }
  if(name==='deal'){
   const pipe=items('core_pipelines').find(x=>x.is_default)||items('core_pipelines')[0];const stage=items('core_stages').find(x=>x.id===d.stage_id);if(!pipe||!stage)throw Error('Pipeline não configurado');
   const body={name:String(d.name).trim(),value:Number(d.value||0),contact_id:d.contact_id,pipeline_id:pipe.id,stage_id:d.stage_id,status:stage.outcome==='open'?'open':stage.outcome,owner_id:optional(d.owner_id),expected_close:optional(d.expected_close),notes:String(d.notes||'')};
   if(s.role==='sdr'){
    if(d.id)await api.rpc('core_sdr_qualify_deal',{w:s.workspace,p_deal:String(d.id),p_stage:String(d.stage_id)});
    else await api.rpc('core_sdr_create_deal',{w:s.workspace,p_contact:String(d.contact_id),p_pipeline:pipe.id,p_stage:String(d.stage_id),p_name:body.name,p_value:body.value,p_notes:body.notes});
   }else{
    if(!canDealEdit())throw Error('Sem permissão para alterar negócios.');
    if(d.id)await api.update('core_deals',String(d.id),s.workspace,body);else await api.insert('core_deals',{workspace_id:s.workspace,...body});
   }
   closeOverlay();toast('Negócio salvo.');await navigate('pipeline');return
  }
  if(name==='task'){
   if(!canTaskWrite())throw Error('Sem permissão para alterar tarefas.');
   const body={title:String(d.title).trim(),due_at:iso(d.due_at),priority:d.priority,status:d.status,assigned_to:optional(d.assigned_to),contact_id:optional(d.contact_id),description:String(d.description||'')};
   if(d.id)await api.update('core_tasks',String(d.id),s.workspace,body);else await api.insert('core_tasks',{workspace_id:s.workspace,...body});
   closeOverlay();toast('Tarefa salva.');await navigate('tasks');return
  }
  if(name==='campaign'){
   if(!canMarketingWrite())throw Error('Sem permissão para alterar campanhas.');
   const body=campaignMutationFromForm({name:d.name,channel:optional(d.channel),budget:d.budget,spent:d.spent,status:d.status,start_date:optional(d.start_date),end_date:optional(d.end_date)});
   if(d.id)await api.update('core_campaigns',String(d.id),s.workspace,body);else await api.insert('core_campaigns',{workspace_id:s.workspace,...body});
   closeOverlay();toast('Campanha salva.');await navigate('campaigns');return
  }
  if(name==='segment'){
   const controller=createSegmentListController(api,s.workspace,{canCreateLists:canSegmentsWrite(),canUpdateLists:canSegmentsWrite(),canDeleteLists:canSegmentsWrite(),canManageMembership:canManageSegmentMembership()});const input={name:String(d.name),category:String(d.category) as 'RECOVERY'|'MARKETING'|'CUSTOM',description:optional(d.description)};
   if(d.id)await controller.update(String(d.id),input);else await controller.create(input);closeOverlay();toast('Lista salva.');await navigate('segments');return
  }
  if(name==='segment-member'){
   if(!d.contact_id){closeOverlay();return}const controller=createSegmentListController(api,s.workspace,{canCreateLists:false,canUpdateLists:false,canDeleteLists:false,canManageMembership:canManageSegmentMembership()});await controller.addMember(String(d.list_id),{contactId:String(d.contact_id),reason:optional(d.reason)});closeOverlay();toast('Contato adicionado à lista.');await navigate('segments');return
  }
  if(name==='report'){
   if(!canReportsRead())throw Error('Sem a capacidade reports.read.');const created=await api.fn('core-report-jobs',{action:'create',workspace_id:s.workspace,kind:String(d.kind),format:'CSV',filters:{}});const jobId=String(created.id||'');if(!jobId)throw Error('O serviço de relatórios não retornou o job.');const progress=document.createElement('p');progress.className='job-progress';form.querySelector('.modal-body')?.append(progress);
   await pollJob(async()=>{const job=await api.fn('core-report-jobs',{action:'status',job_id:jobId});return {status:String(job.status),processed:Number(job.emitted_row_count||0),total:Number(job.expected_row_count||0)}},progress,750);closeOverlay();toast('Relatório pronto para download.');await navigate('reports');return
  }
  if(name==='rule'){
   if(!canMarketingWrite())throw Error('Sem permissão para alterar automações.');
   const body={name:String(d.name).trim(),task_title:String(d.task_title).trim(),due_hours:Number(d.due_hours),enabled:!!form.querySelector<HTMLInputElement>('input[name=enabled]')?.checked};
   if(d.id)await api.update('core_automation_rules',String(d.id),s.workspace,body);else await api.insert('core_automation_rules',{workspace_id:s.workspace,...body});
   closeOverlay();toast('Automação salva.');await navigate('automations');return
  }
  if(name==='note'){if(!String(d.body||'').trim())throw Error('Nota vazia');await api.insert('core_activities',{workspace_id:s.workspace,contact_id:d.contact_id,kind:'note',body:String(d.body).trim()});closeOverlay();toast('Atividade registrada.');await showContact(String(d.contact_id));return}
  if(name==='contact-tags'){
   const chosen=new Set([...form.querySelectorAll<HTMLInputElement>('input[name^=tag_]:checked')].map(x=>x.name.slice(4)));
   const existing=await api.select('core_contact_tags',{workspace_id:`eq.${s.workspace}`,contact_id:`eq.${d.contact_id}`});const old=new Set(existing.map((x:Row)=>x.tag_id));
   for(const id of chosen){if(!old.has(id))await api.insert('core_contact_tags',{workspace_id:s.workspace,contact_id:d.contact_id,tag_id:id})}
   for(const id of old as Set<string>){if(!chosen.has(id))await api.request(`/rest/v1/core_contact_tags?${api.q({workspace_id:`eq.${s.workspace}`,contact_id:`eq.${d.contact_id}`,tag_id:`eq.${id}`})}`,{method:'DELETE'})}
   closeOverlay();toast('Tags atualizadas.');await showContact(String(d.contact_id));return
  }
  if(name==='tag'){await api.insert('core_tags',{workspace_id:s.workspace,name:String(d.name).trim(),color:d.color});closeOverlay();toast('Tag criada.');await navigate('settings');return}
  if(name==='form'){await api.insert('core_forms',{workspace_id:s.workspace,name:String(d.name).trim(),slug:toSlug(String(d.slug)),source:optional(d.source)});closeOverlay();toast('Formulário cadastrado.');await navigate('integrations');return}
  if(name==='member-invite'||name==='member-update'){
   if(!canAdmin())throw Error('Somente administradores gerenciam membros');const body=name==='member-invite'?{workspace_id:s.workspace,action:'invite',email:String(d.email).toLowerCase(),role:d.role}:{workspace_id:s.workspace,action:'update',user_id:d.user_id,role:d.role};
   const r=await api.fn('core-invite-member',body);closeOverlay();toast(name==='member-invite'?(r.delivery==='auth_email'||r.delivery==='auth_recovery'?'Convite enviado por e-mail.':'Convite salvo, mas o e-mail não pôde ser enviado.'):'Acesso atualizado.');await navigate('team');return
  }
  if(name==='import-csv'){const f= (new FormData(form).get('file')) as File;if(!f||!f.size)throw Error('Selecione o arquivo CSV');const progress=el('import-progress');if(!progress)throw Error('Indicador de importação indisponível.');await importCSV(f,progress);setTimeout(()=>{closeOverlay();void navigate('contacts')},1200);return}
 }catch(e){fail(e)}finally{if(btn){btn.disabled=false;btn.innerHTML=originalButtonHtml}}
}

document.addEventListener('click',e=>{
 const nav=(e.target as HTMLElement).closest<HTMLElement>('[data-nav]');if(nav){closeOverlay();void navigate(nav.dataset.nav as Page);return}
 const target=(e.target as HTMLElement).closest<HTMLElement>('[data-action]');if(target){e.preventDefault();void clickAction(target.dataset.action||'',target.dataset.id||'',target).catch(fail)}
});
document.addEventListener('submit',e=>{const form=e.target as HTMLFormElement;if(form.matches('form[data-form]')){e.preventDefault();void submitForm(form)}});
document.addEventListener('input',e=>{const target=e.target as HTMLInputElement;if(target.id==='contacts-search'){s.query=target.value;const node=el('contacts-table');if(node)node.innerHTML=contactTable(contactRows());const count=el('contacts-count');if(count)count.textContent=`${contactRows().length} contato(s) exibido(s)`;}});
document.addEventListener('change',e=>{const target=e.target as HTMLInputElement;
 if(target.dataset.permission){void api.rpc('core_team_set_permission',{w:s.workspace,p_role:target.dataset.role,p_permission:target.dataset.permission,p_enabled:target.checked}).then(()=>toast('Permissão atualizada.')).catch(fail);return}
 if(target.id==='contacts-status'){s.status=target.value;const node=el('contacts-table');if(node)node.innerHTML=contactTable(contactRows());const count=el('contacts-count');if(count)count.textContent=`${contactRows().length} contato(s) exibido(s)`;return}
 if(target.id==='tasks-overdue'){s.overdueOnly=target.checked;renderPage();return}
 if(target.id==='tasks-completed'){s.showCompleted=target.checked;renderPage();return}
 if(target.dataset.taskCheck){const id=target.dataset.taskCheck;void api.update('core_tasks',id,s.workspace,{status:target.checked?'done':'todo'}).then(()=>navigate('tasks')).catch(fail);return}
 if(target.name==='name'&&target.closest('form[data-form="create-workspace"]')){const slug=target.closest('form')?.querySelector<HTMLInputElement>('[name=slug]');if(slug&&!slug.dataset.edited)slug.value=toSlug(target.value);return}
 if(target.name==='slug')target.dataset.edited='true';
});
let dragging='';
document.addEventListener('dragstart',e=>{const card=(e.target as HTMLElement).closest<HTMLElement>('[data-deal]');if(card&&(canDealEdit()||(s.role==='sdr'&&items('core_deals').find(d=>d.id===card.dataset.deal)?.owner_id===s.user?.id))){dragging=card.dataset.deal||'';e.dataTransfer?.setData('text/plain',dragging);if(e.dataTransfer)e.dataTransfer.effectAllowed='move'}});
document.addEventListener('dragover',e=>{const col=(e.target as HTMLElement).closest<HTMLElement>('[data-stage]');if(col&&dragging){e.preventDefault();col.classList.add('drag-over')}});
document.addEventListener('dragleave',e=>{const col=(e.target as HTMLElement).closest<HTMLElement>('[data-stage]');if(col&&!col.contains(e.relatedTarget as Node))col.classList.remove('drag-over')});
document.addEventListener('drop',e=>{const col=(e.target as HTMLElement).closest<HTMLElement>('[data-stage]');if(!col||!dragging)return;e.preventDefault();col.classList.remove('drag-over');const deal=dragging;dragging='';const stage=items('core_stages').find(x=>x.id===col.dataset.stage);if(!stage)return;
 const move=s.role==='sdr'?api.rpc('core_sdr_qualify_deal',{w:s.workspace,p_deal:deal,p_stage:stage.id}):api.update('core_deals',deal,s.workspace,{stage_id:stage.id,status:stage.outcome==='open'?'open':stage.outcome});
 void move.then(async()=>{toast('Negócio movido e salvo.');await navigate('pipeline')}).catch(fail)
});
document.addEventListener('dragend',()=>{dragging='';document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.target as HTMLElement).id==='top-search'){const query=(e.target as HTMLInputElement).value.trim();void navigate('contacts').then(()=>{s.query=query;const input=el('contacts-search') as HTMLInputElement|null;if(input)input.value=query;const node=el('contacts-table');if(node)node.innerHTML=contactTable(contactRows());});return}if(e.key==='Escape')closeOverlay();if(e.key==='Enter'&&(e.target as HTMLElement).matches('.deal-card')){const id=(e.target as HTMLElement).dataset.deal;void dealModal(id)}});
void boot();
